WITH remaining_keys AS (SELECT id, supplier_id FROM products INTERSECT SELECT id, supplier_id FROM products WHERE cost > 650), kept_rows AS (SELECT s.* FROM products s JOIN remaining_keys k ON s.id = k.id AND s.supplier_id = k.supplier_id) SELECT s.id, s.category, s.brand, s.price, s.stock_qty, s.launch_date, s.tags, s.supplier_id, CASE WHEN category RLIKE '^(Fashion|Grocery)$' THEN 'GROUP_B' ELSE 'GROUP_A' END AS category_zone, (SELECT SUM(t2.price) FROM products t2 WHERE t2.supplier_id = s.supplier_id) AS sum_product_price FROM kept_rows s ORDER BY launch_date
